package discovery

import (
	"context"
	"sync"
)

// WorkflowState records workflow IDs returned by list_workflows for one
// selection context. Retries and later discovery calls share this object.
type WorkflowState struct {
	mu  sync.RWMutex
	ids map[string]struct{}
}

func NewWorkflowState() *WorkflowState {
	return &WorkflowState{ids: make(map[string]struct{})}
}

// Add records every non-empty workflow ID returned by discovery.
func (s *WorkflowState) Add(workflowIDs ...string) {
	if s == nil {
		return
	}
	s.mu.Lock()
	defer s.mu.Unlock()
	if s.ids == nil {
		s.ids = make(map[string]struct{})
	}
	for _, id := range workflowIDs {
		if id != "" {
			s.ids[id] = struct{}{}
		}
	}
}

func (s *WorkflowState) Contains(workflowID string) bool {
	if s == nil {
		return false
	}
	s.mu.RLock()
	defer s.mu.RUnlock()
	_, ok := s.ids[workflowID]
	return ok
}

package tools

import (
	"context"

	"example.com/synthetic-workflow-discovery/internal/discovery"
)

func ListWorkflows(ctx context.Context, catalog *discovery.WorkflowCatalog, state *discovery.WorkflowState, filters discovery.DiscoveryFilters) []discovery.Workflow {
	workflows := catalog.ListWorkflows(ctx, filters)
	ids := make([]string, 0, len(workflows))
	for _, workflow := range workflows {
		ids = append(ids, workflow.ID)
	}
	RecordDiscovered(state, ids)
	return workflows
}

func RecordDiscovered(state *discovery.WorkflowState, workflowIDs []string) {
	if state != nil {
		state.Add(workflowIDs...)
	}
}

func (v *Validator) SetWorkflowState(state *discovery.WorkflowState) {
	v.state = state
}

// IsAllowed requires catalog membership and, when state is attached, current
// list_workflows membership.
func (v *Validator) IsAllowed(workflowID string) bool {
	if _, ok := v.allowed[workflowID]; !ok {
		return false
	}
	return v.state == nil || v.state.Contains(workflowID)
}

func (v *Validator) Validate(workflowID string) error {
	if v.IsAllowed(workflowID) {
		return nil
	}
	return &ValidationError{WorkflowID: workflowID, Reason: "not in current discovery result"}
}

