import (
	"context"
	"fmt"

	"example.com/synthetic-workflow-discovery/internal/discovery"
)

type DiscoveryResult struct {
	Recommended string
	Alternatives []string
}

func isWorkflowInDiscoveryResult(workflowID string, result DiscoveryResult) bool {
	if result.Recommended == workflowID {
		return true
	}
	for _, alternative := range result.Alternatives {
		if alternative == workflowID {
			return true
		}
	}
	return false
}

func authorizeSelectionDriver(workflowID string, result DiscoveryResult) error {
	if !isWorkflowInDiscoveryResult(workflowID, result) {
		return fmt.Errorf("workflow %q was not discovered", workflowID)
	}
	return nil
}

func (s *WorkflowState) Contains(workflowID string) bool {
	if s == nil {
		return false
	}
	s.mu.RLock()
	defer s.mu.RUnlock()
	_, ok := s.ids[workflowID]
	return ok
}

type workflowStateKey struct{}

func WithWorkflowState(ctx context.Context, state *WorkflowState) context.Context {
	return context.WithValue(ctx, workflowStateKey{}, state)
}

func WorkflowStateFromContext(ctx context.Context) (*WorkflowState, bool) {
	state, ok := ctx.Value(workflowStateKey{}).(*WorkflowState)
	return state, ok && state != nil
}

